import std.concurrent as conc

pub type AppError = Failed(String)

pub fn main() -> Result<(), AppError> {
    let a = scope { 5 }
    let b = scope collectAll { a }
    let r = scope timeout(500) { b }
    let c = scope timeout(500) collectAll { 7 }
    let n = match r {
        Ok(v) => v
        Err(e) => 0
    }
    let m = match c {
        Ok(v) => v
        Err(e) => 0
    }
    let _ = n
    let _ = m
    return Ok(())
}

